shell_commands:
/bin/zsh -lc "cat > src/orchestration/chatOrchestrator.beforeSession.test.ts <<'EOF'
import {expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

it('specs/hal-engine-config-hooks/spec.md#10 calls onError with the session and beforeSession error', async () => {
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const failure = new Error('setup failed');
  let reported: [ChatSession, Error] | undefined;
  const provider: AIProvider = {
    async *sendMessage() {},
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const promptBuilder = new PromptBuilder({
    baseSystemPrompt: 'HAL',
    systemPromptSuffix: '',
    contextConfig: {historyLength: 10, includeTimestamps: false, includeSystemPrompt: true},
  });
  const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {
    hooks: {
      beforeSession: async () => { throw failure; },
      onError: async (receivedSession, error) => { reported = [receivedSession, error]; },
    },
  });

  await expect(orchestrator.processMessage(session)).rejects.toBe(failure);
  expect(reported).toEqual([session, failure]);
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/chatOrchestrator.beforeSession.test.ts"
